cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./github) || exit 1; for i in $I; do case $i in context|encoding/json|errors|fmt|io|net/http|net/url|strings|time) ;; *) echo "imports: package github imports $i (allowed: context, encoding/json, errors, fmt, io, net/http, net/url, strings, time)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' github/access.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' github/access.go 2>&1); [ -z "$C" ] || { echo "clock: github/access.go reads time.Now or time.Since (the clock is the now argument)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head; do C=$(gofmt -l -r "$x -> http.NoBody" github/access.go 2>&1); [ -z "$C" ] || { echo "net: github/access.go uses $x (every HTTP call goes through the injected Do)"; exit 1; }; done
